import React, { useEffect, useState } from 'react';
import API from '../api';
import { useNavigate, Link } from 'react-router-dom';
import { addToCart } from '../cart';

function Products() {
  const [products, setProducts] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState('default');
  const [error, setError] = useState('');
  const [added, setAdded] = useState({});
  const navigate = useNavigate();

  useEffect(() => {
    fetchProducts();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [search, sortBy, products]);

  const fetchProducts = async () => {
    try {
      const res = await API.get('/products/');
      setProducts(res.data);
      setFiltered(res.data);
    } catch (err) {
      setError('Failed to load products');
    }
  };

  const applyFilters = () => {
    let result = [...products];

    if (search) {
      result = result.filter(p =>
        p.name.toLowerCase().includes(search.toLowerCase()) ||
        p.description.toLowerCase().includes(search.toLowerCase())
      );
    }

    if (sortBy === 'low') result.sort((a, b) => a.price - b.price);
    else if (sortBy === 'high') result.sort((a, b) => b.price - a.price);
    else if (sortBy === 'name') result.sort((a, b) => a.name.localeCompare(b.name));

    setFiltered(result);
  };

  const handleAddToCart = (product) => {
    addToCart(product);
    setAdded(prev => ({ ...prev, [product.id]: true }));
    setTimeout(() => setAdded(prev => ({ ...prev, [product.id]: false })), 1500);
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  const token = localStorage.getItem('token');

  return (
    <div style={styles.container}>
      <div style={styles.navbar}>
        <h2 style={styles.logo}>🛒 Ecommerce</h2>
        <div style={styles.navLinks}>
          <Link to="/cart" style={styles.navLink}>🛒 Cart</Link>
          {token ? (
            <>
              <Link to="/orders" style={styles.navLink}>My Orders</Link>
              <button onClick={handleLogout} style={styles.logoutBtn}>Logout</button>
            </>
          ) : (
            <Link to="/login" style={styles.navLink}>Login</Link>
          )}
        </div>
      </div>

      <div style={styles.body}>
        <h3 style={styles.heading}>All Products</h3>

        {/* Search and Filter Bar */}
        <div style={styles.filterBar}>
          <input
            style={styles.searchInput}
            type="text"
            placeholder="🔍 Search products..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          <select
            style={styles.select}
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
          >
            <option value="default">Sort By</option>
            <option value="low">Price: Low to High</option>
            <option value="high">Price: High to Low</option>
            <option value="name">Name: A to Z</option>
          </select>
        </div>

        {/* Results count */}
        <p style={styles.resultCount}>
          {filtered.length} product{filtered.length !== 1 ? 's' : ''} found
          {search && ` for "${search}"`}
        </p>

        {error && <p style={styles.error}>{error}</p>}

        {filtered.length === 0 && !error && (
          <div style={styles.noResults}>
            <p>No products found matching your search.</p>
            <button style={styles.clearBtn} onClick={() => { setSearch(''); setSortBy('default'); }}>
              Clear Filters
            </button>
          </div>
        )}

        <div style={styles.grid}>
          {filtered.map((p) => (
            <div key={p.id} style={styles.card}>
              <div style={styles.cardTop}>
                {p.stock === 0 && <span style={styles.outOfStockBadge}>Out of Stock</span>}
                {p.stock > 0 && p.stock <= 5 && <span style={styles.lowStockBadge}>Only {p.stock} left!</span>}
              </div>
              <h4 style={styles.productName}>{p.name}</h4>
              <p style={styles.desc}>{p.description}</p>
              <p style={styles.price}>${p.price}</p>
              <p style={styles.stock}>In Stock: {p.stock}</p>
              <button
                style={{
                  ...styles.cartBtn,
                  background: added[p.id] ? '#4CAF50' : p.stock === 0 ? '#ccc' : '#2196F3',
                  cursor: p.stock === 0 ? 'not-allowed' : 'pointer'
                }}
                onClick={() => handleAddToCart(p)}
                disabled={p.stock === 0}
              >
                {p.stock === 0 ? 'Out of Stock' : added[p.id] ? '✓ Added!' : 'Add to Cart'}
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: { minHeight: '100vh', background: '#f0f2f5' },
  navbar: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: '#fff', padding: '15px 30px', boxShadow: '0 2px 5px rgba(0,0,0,0.1)' },
  logo: { margin: 0 },
  navLinks: { display: 'flex', alignItems: 'center', gap: '20px' },
  navLink: { color: '#2196F3', textDecoration: 'none', fontWeight: 'bold' },
  logoutBtn: { padding: '8px 16px', background: '#f44336', color: '#fff', border: 'none', borderRadius: '5px', cursor: 'pointer' },
  body: { padding: '30px' },
  heading: { marginBottom: '15px', fontSize: '22px' },
  filterBar: { display: 'flex', gap: '15px', marginBottom: '10px', flexWrap: 'wrap' },
  searchInput: { flex: 1, minWidth: '200px', padding: '10px 15px', borderRadius: '8px', border: '1px solid #ddd', fontSize: '15px', outline: 'none' },
  select: { padding: '10px 15px', borderRadius: '8px', border: '1px solid #ddd', fontSize: '15px', background: '#fff', cursor: 'pointer' },
  resultCount: { color: '#888', fontSize: '14px', marginBottom: '20px' },
  error: { color: 'red' },
  noResults: { textAlign: 'center', padding: '40px', color: '#666' },
  clearBtn: { marginTop: '10px', padding: '8px 20px', background: '#2196F3', color: '#fff', border: 'none', borderRadius: '5px', cursor: 'pointer' },
  grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: '20px' },
  card: { background: '#fff', padding: '20px', borderRadius: '10px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)', position: 'relative' },
  cardTop: { minHeight: '24px', marginBottom: '8px' },
  outOfStockBadge: { background: '#f44336', color: '#fff', padding: '3px 8px', borderRadius: '4px', fontSize: '12px' },
  lowStockBadge: { background: '#FF9800', color: '#fff', padding: '3px 8px', borderRadius: '4px', fontSize: '12px' },
  productName: { margin: '0 0 8px', fontSize: '18px' },
  desc: { color: '#666', fontSize: '14px' },
  price: { fontWeight: 'bold', fontSize: '18px', color: '#4CAF50' },
  stock: { fontSize: '13px', color: '#999' },
  cartBtn: { width: '100%', padding: '10px', color: '#fff', border: 'none', borderRadius: '5px', fontSize: '15px', marginTop: '10px' },
};

export default Products;
